//! Component dumps of the draw widgets: each one's resolved style (its pure `style` function) in
//! every built-in and mode, as text under `tests/dumps/components/`. Rewrite with
//! `UPDATE_DUMPS=1 cargo test -p craft-draw --features ui --test control_dumps`.

use craft_draw::ui::{BezierOverlay, GradientEditor, GradientOverlay, PenDraft, TransformBox};
use craft_ui::presets::style::PresetStyle;

use craft_ui::testing::dump::{Dump, check_component};
use craft_ui::theme::UiTokens;

const HEADER: &str =
    "Generated by crates/draw/tests/control_dumps.rs; rewrite with UPDATE_DUMPS=1 cargo test -p craft-draw --features ui --test control_dumps";

fn check(file: &str, each: impl FnMut(&mut Dump, &UiTokens)) {
    check_component(format!("{}/tests/dumps/components/{file}", env!("CARGO_MANIFEST_DIR")), HEADER, each);
}

/// Gradient editors: the bar's sizes, the ramp's checkerboard and edge, the marker colours and
/// the drop line.
#[test]
fn gradient_editor() {
    check("gradient_editor.txt", |d, t| {
        let s = GradientEditor::style(t);
        d.line("ramp_height", s.ramp_height).line("inset", s.inset).line("marker", s.marker).line("pointer", s.pointer).line("diamond", s.diamond);
        d.line("hit", s.hit).line("diamond_hit", s.diamond_hit).line("tear_off", s.tear_off).line("drop_line", s.drop_line);
        d.line("checker_a", s.ramp.checker[0]).line("checker_b", s.ramp.checker[1]).line("cell", s.ramp.cell).line("edge", s.ramp.edge);
        d.line("marker_edge", s.marker_edge).line("hovered", s.hovered).line("selected", s.selected).line("drop", s.drop);
    });
}

/// Gradient lines: the line and its outline, the mirrored dash, the end rings, the stop discs and
/// rings, the diamonds, the selected colour, the hit, click slop and tear-off distances.
#[test]
fn gradient_line() {
    check("gradient_line.txt", |d, t| {
        let s = GradientOverlay::style(t);
        d.line("line", s.line).line("halo", s.halo).line("dash", s.dash.0).line("gap", s.dash.1);
        d.line("end_ring", s.end_ring).line("end", s.end).line("end_halo", s.end_halo);
        d.line("stop", s.stop).line("stop_ring", s.stop_ring).line("stop_halo", s.stop_halo);
        d.line("diamond", s.diamond).line("diamond_fill", s.diamond_fill).line("diamond_halo", s.diamond_halo);
        d.line("selected", s.selected).line("backing", s.backing);
        d.line("hit", s.hit).line("click_slop", s.click_slop).line("tear_off", s.tear_off);
    });
}

#[test]
fn gradient_palette() {
    check("gradient_palette.txt", |d, t| {
        let g = t.component.gradient_palette;
        let ring = PresetStyle::from_tokens(t);
        d.line("cell_width", g.cell_width)
            .line("cell_height", g.cell_height)
            .line("list_swatch_width", g.list_swatch_width)
            .line("list_swatch_height", g.list_swatch_height)
            .line("max_height", g.max_height)
            .line("ring_selected", ring.ring_selected)
            .line("ring_halo", ring.ring_halo);
    });
}

/// Paths: outline and selected segment widths, the default path colour, the anchor, selected
/// anchor and handle end looks, the handle line, hit, click slop and flattening tolerance.
#[test]
fn bezier() {
    check("bezier.txt", |d, t| {
        let s = BezierOverlay::style(t);
        d.line("line", s.line).line("selected_segment", s.selected_segment).line("color", s.color);
        for (key, h) in [("anchor", &s.anchor), ("selected_anchor", &s.selected_anchor), ("control", &s.control)] {
            d.line(&format!("{key}.size"), h.size).line(&format!("{key}.fill"), h.fill);
            d.line(&format!("{key}.stroke"), h.stroke).line(&format!("{key}.halo"), h.halo);
        }
        d.line("control_line", s.control_line).line("hit", s.hit).line("click_slop", s.click_slop).line("flatten", s.flatten);
    });
}

/// The pen draft: the path so far, the rubber band's width and dashes, the anchor looks, the close
/// cue's anchor, ring and offset, the hit and click slop.
#[test]
fn pen() {
    check("pen.txt", |d, t| {
        let s = PenDraft::style(t);
        d.line("draft_line", s.draft_line).line("color", s.color);
        d.line("rubber_width", s.rubber_width).line("rubber_dash", s.rubber_dash).line("rubber_gap", s.rubber_gap);
        for (key, h) in [("anchor", &s.anchor), ("selected_anchor", &s.selected_anchor), ("control", &s.control), ("close_anchor", &s.close_anchor)] {
            d.line(&format!("{key}.size"), h.size).line(&format!("{key}.fill"), h.fill);
            d.line(&format!("{key}.stroke"), h.stroke).line(&format!("{key}.halo"), h.halo);
        }
        d.line("control_line", s.control_line).line("close_ring", s.close_ring).line("close_offset", s.close_offset);
        d.line("hit", s.hit).line("click_slop", s.click_slop).line("flatten", s.flatten);
    });
}

/// Transform boxes: the box line, the reach of handles, the rotate zones and a click, the
/// reference point's sizes and lines, and the focus line round the whole box.
#[test]
fn transform() {
    check("transform.txt", |d, t| {
        let s = TransformBox::style(t);
        d.line("line", s.line).line("handle_size", s.handle.size).line("hit", s.hit).line("rotate_reach", s.rotate_reach);
        d.line("band_inner", s.band_inner).line("band_outer", s.band_outer).line("click_slop", s.click_slop);
        d.line("pivot_radius", s.pivot_radius).line("pivot_arm", s.pivot_arm).line("pivot", s.pivot).line("pivot_halo", s.pivot_halo);
        d.line("focus", s.focus).line("focus_halo", s.focus_halo).line("focus_offset", s.focus_offset);
    });
}
